          ('step 3');
          if (game.roundNumber != 1) {
            player.chooseTarget('【先领】:你可以令一名其他角色执行一次相同的流程', function (card, player, target) {
              return target != player;
            }).ai = function (target) {
              return get.attitude(target, player) > 0;
            };
          } else event.finish();
