      junxingmrfz_info: '①你每回合的第X个阶段结束时,你可以与你一名攻击范围内的其他角色进行拼点,若你赢,你视为对其使用一张【杀】,反之,其视为对你使用一张【杀】.(X=你本回合造成的伤害数)</br>②锁定技,体力值不大于你的其他角色不能响应你使用的牌.</br>③锁定技,当你已损失体力值小于2时,你获得【同协】,反之你每回合的第一张【杀】额外结算一次.',
