      xuehengmrfz_info: '觉醒技,回合开始时,若你体力上限不少于存活角色数,你失去【聚火】且:若你的手牌数大于你的体力值且没有与你胜利条件一致的角色死亡,获得【熯天】,反之你将身份牌变为内奸(如果你是主公则改为将其余角色的身份牌均变为反贼),获得【失魂】.你将体力值调整至体力上限',
      hantianmrfz: '熯天',
      hantianmrfz_info: '①锁定技,准备阶段,若场上没有角色有‘志城’标记,你令与你胜利条件相同的其他角色和你获得‘志城’标记,所有拥有‘志城’标记的角色将体力上限和体力值调整至所有有‘志城’标记的角色中的体力上限的最大值.②当拥有‘志城’标记的角色使用的【杀】结算完毕后,其他有‘志城’标记的角色可以对此杀的目标使用一张【杀】并摸一张牌.',
      shihunmrfz: '失魂',
      shihunmrfz_info: '锁定技,准备阶段,你对所有角色造成两点火属性伤害;当你受到大于1点的伤害时,你将伤害值调整至1点;你使用牌无次数限制;结束阶段,你摸X张牌.(X=已死亡的角色数)',
      budaomrfz: '布道',
      budaomrfz_info: '①出牌阶段,你可以将一张黑色牌置于你攻击范围内的一名其他角色的判定区.②锁定技,摸牌阶段你额外摸X张牌(X=场上判定区内牌的数量).',
      zhuranmrfz: '逐燃',
      zhuranmrfz_info: '锁定技,其他角色的回合开始阶段,',
      bojimrfz: '博济',
      bojimrfz_info: '出牌阶段限一次,你可以展示一张手牌,其他角色依次展示一张手牌,与你展示的牌颜色相同的角色和你被称为<博济角色>,直到你的下个出牌阶段开始时,所有<博济角色>可以将其他<博济角色>的手牌如手牌般使用或打出且当你的手牌小于X时,你将手牌补至X张(X = <博济角色>数).<br><span style="font-family: yuanli">"如有博施于民,而能济众,何如？可谓仁乎？"</span>',
      caijianmrfz: '裁剪',
      caijianmrfz_info: '锁定技,当你死亡时,击杀你的角色弃置区域内所有牌、失去武将牌上的所有技能并且复原武将牌,其随机获得场上角色武将牌上的两个技能并摸3张牌.<br><span style="font-family: yuanli">"你葬送我的未来,我剪断你的过去."</span>',
      yuanfumrfz: '怨府',
      yuanfumrfz_info: '锁定技,摸牌阶段结束时,你展示一张手牌,其他角色不能在非濒死状态下使用或打出与你展示的牌相同的手牌且你于本回合结束时失去一点体力并摸X张牌.(X = 你本回合造成的伤害,X至多为5)<br><span style="font-family: yuanli">"皇太子副主,望其所爱,硕帝之宠臣,而子违之,所谓三怨成府者也."</span>',
      fenzhoumrfz: '焚舟',
      fenzhoumrfz_info: '出牌阶段限一次,你可以废除你的一个装备栏,所有其他角色选择一项:1.弃置一张牌,本回合其下次受到的伤害+1;2.交给你一张牌,本回合你使用【杀】的次数+1;3.令你摸一张牌,本回合你下次造成的伤害+1.<br><span style="font-family: yuanli">"秦伯伐晋,济河焚舟."</span>',
      jujumrfz: '踽踽',
      jujumrfz_info: '锁定技,准备阶段,若你有被废弃的装备栏且你击杀过一名其他角色,你选择流失一点体力或失去一点体力上限,你回复一个装备栏.<br><span style="font-family: yuanli">"有杕之杜,其叶湑湑,独行踽踽."</span>',
      chongxiemrfz: '统械',
