      amy_qingyanmrfz: '青焱',
      amy_qingyanmrfz_info: '①锁定技,[你使用【杀】的次数+1],{你每回合使用的第一张【杀】的伤害基数+1},(你使用的【杀】需要两张【闪】才可抵消).</br>②出牌阶段结束时,你可以删除【青焱①】中[]、{}或()的内容直到本轮结束,令一名其他角色获得你删除的内容的效果直到其回合结束.',
      yingxiaomrfz: '影霄',
      yingxiaomrfz_info: '限定技,准备阶段,若你已经使用了至少5张【杀】,你可以依次使用1张雷【杀】、1张火【杀】和1张伤害基数+2且无视防具的【杀】(目标必须合法),结算完成后,你摸X张牌、手牌上限+X且接下来两轮内,你造成的伤害均为体力流失.(X=你因此技能使用的【杀】造成的伤害数)',
      jifengmrfz: '极锋',
      jifengmrfz_info: '当你使用【杀】选择唯一目标后,你可以执行所有符合条件的选项:1.若其防具栏不为空,你无视其防具;2.若其有护甲值,你无视此护甲;3.若其有手牌,此【杀】须要两张【闪】才可抵消,若你本回没有使用过此技能,你摸X张牌.(X=未执行的选项数)',
      xiqiaomrfz: '细巧',
      xiqiaomrfz_info: '每回合限一次,当你需要使用或打出【闪】时,你可以弃置一张牌,摸一张牌并展示之,若与你弃置的牌类别不同,视为你使用或打出了一张【闪】.',
      tianyimrfz: '天仪',
      tianyimrfz_info: '转换技,一名角色的判定阶段,你可以,阳:观看牌堆顶两张牌,并将其置于牌堆顶或牌堆底;阴:进行一次判定,并获得判定牌,本回合此牌视为【闪】,若判定结果为♣️️,你本局游戏使用【杀】的次数+1(至多+3).',
      huijianmrfz: '辉剑',
      huijianmrfz_info: '出牌阶段限一次,当你使用单一目标的基本和普通锦囊牌选择目标后,若【天仪】状态为阴,你可以令此牌额外指定任意名(至多为你本回合剩余使用【杀】的次数)其他角色为目标(目标必须合法),你本阶段减少等量使用【杀】的次数.',
      bingmingmrfz: '病鸣',
      bingmingmrfz_info: '锁定技,第二轮开始时,若场上有星源,你将手牌和手牌上限调整至与其一致.',
      daoliumrfz: '导流',
