      yinshimrfz: '隐市',
      yinshimrfz_info: '锁定技,你的回合外,你不能成为任意角色于本回合使用的前X张牌的目标.(X=你有牌的区域数)',
      lingdingmrfz: '凌顶',
      lingdingmrfz_info: '当你使用或打出牌时,你记录之,若你记录的牌数不小于 [ 1 ],你可以摸 [ 1 ] 张牌,你令 [ ] 中的数字+1(不能超过你的体力上限)并清除此技能你记录的牌',
      yabengmrfz: '崖崩',
      yabengmrfz_info: '锁定技,当你进入濒死状态时,你重置【凌顶】并摸X张牌.(X=【凌顶】记录的牌的数量,X至多为2)',
      shengnvmrfz: '圣女',
      shengnvmrfz_info: '出牌阶段限一次,你可以选择两名其他角色,这两名角色同时选择一项:<br>1.收回所有装备区的牌;<br>2.将一张手牌当作【乐不思蜀】置入其的判定区;<br>3.不能响应下一张指定其为目标的基本牌或普通锦囊牌.<br>若这些角色选择的选项不同,你获得这些角色一张牌,反之你摸两张牌.',
      shenshemrfz: '神慑',
      shenshemrfz_info: '锁定技.<br>①结束阶段,若你没有明置的手牌,你明置你的手牌<br>②当你成为其他角色使用的带有伤害类标签的牌的目标后,若此牌的点数不大于你明置的牌中点数最大的一张牌,则其须弃置手牌区和装备区内各一张牌.',
      xiedumrfz: '蝎毒',
      xiedumrfz_info: '①锁定技,你的【毒】视为【杀】.<br>②当你[使用的【杀】/于回合外]对一名其他角色造成伤害后,你可以选择其一张牌(若为装备区的牌则改为弃置之),其将此牌转化为【毒】.',
      lijimrfz: '力积',
      lijimrfz_info: '锁定技,你使用的【杀】需要X张【闪】才可抵消.(X=本回合你使用的牌的花色数)',
      qianzongmrfz: '潜踪',
      qianzongmrfz_info: '①隐匿技,当你登场后,若当前回合角色不为你,你可以对当前回合角色造成一点伤害,反之,你摸一张牌或回复一点体力.<br>②你的回合结束时,若你本回合没有因弃置而失去牌,你可以进入隐匿状态.',
      chihenmrfz: '齿痕',
      chihenmrfz_info: '锁定技,你的弃牌阶段开始时,若你防具栏有牌,你令至多X名角色获得一个<护>标记;拥有<护>标记的角色手牌上限+X,且成为带有伤害类标签的牌的目标后,若使用者的体力值不大于你的体力值,使用者须弃置一张牌,否则此牌对该角色无效,该角色移除一个<护>标记.(X=该角色‘护’标记的数量)',
      haomingmrfz: '号鸣',
      haomingmrfz_info: '①当你于回合内第一次造成伤害后,你可以从牌堆中获得一张指定类型的牌.<br>②结束阶段,你可以视为一张【决斗】,受到伤害的角色须弃置一半的手牌(向上取整)且其使用牌不能指定有<护>的角色为目标直到其回合结束.<br>③出牌阶段限一次,你可以弃置任意张手牌,从牌堆中获得一张牌名字数等同于弃置的牌数的牌.',
      sheyingmrfz: '摄影',
      sheyingmrfz_info: '①出牌阶段限两次,若场上【镜头】的数量少于4,你可以弃置一张牌,选择将一张【镜头】置入一名其他角色的装备栏.②锁定技,当场上有【镜头】时,你的手牌上限+2,其他角色计算与你的距离+1.',
      jingtoumrfz_show: '镜头',
      jingtoumrfz_show_info: '·武器牌 ♥️️7 攻击距离1<br>·防具牌 ♣️️7<br>·进攻马/防御马 ♠️️7 攻击距离+1/防御距离-1<br>·宝具栏 ♦️️7<br>锁定技,你的手牌始终明置;你始终视为在其他角色的攻击范围内;此牌离开你的装备区时,销毁之.',
      chaozaimrfz: '超载',
      chaozaimrfz_info: '回合开始时,若场上有【镜头】,你可以令所有角色获得如下效果直到你下个回合开始且你下个回合开始时弃置场上所有的【镜头】并摸等量的牌(不计入手牌上限且点数视为7):<br>当你使用牌指定目标后,若该角色装备区内有【镜头】:1.此牌点数[不小于/不大于]【镜头】的点数,则此牌[伤害基数+1/不可响应];2.其装备区内有与此牌花色相同的【镜头】,于此牌结算完成后视为对其使用一张相同的牌(不计入次数限制).',
      biaolimrfz: '表里',
      biaolimrfz_info: '锁定技,出牌阶段开始时,你摸三张牌,若这些牌中[红/黑]色的牌的数量不少于2,则你因此技能而获得的牌视为[【桃】(可以于出牌阶段对任意角色使用)/【杀】(对体力值不小于你的角色无距离限制且不计入使用次数)].',
      ymkongwomrfz: '控我',
      ymkongwomrfz_info: '摸牌阶段结束时,你可以弃置一张牌,观看牌堆顶两张牌,并以任意的顺序将其置于牌堆顶或牌堆底.',
      chunleimrfz: '春雷',
      chunleimrfz_info: '每名角色的准备阶段,你可以弃置一张黑色的牌,你对其造成一点雷电伤害.',
      zheqimrfz: '蛰起',
      zheqimrfz_info: '锁定技,每回合限一次,当有角色受到雷属性伤害后,当前回合角色获得下列效果直到回合结束:1.使用牌无次数限制;2.使用或打出一张非装备牌时,其须弃置一张手牌.此回合结束后,你选择获得其本回合因弃置而进入弃牌堆的牌(每种类型限一张).',
      pianfengmrfz: '偏锋',
      pianfengmrfz_info: '当你对其他角色造成伤害后,若有对应的实体牌,你可以令其回复一点体力,并展示其X张牌,若展示的牌中有与对其造成的伤害的牌类型相同的牌,其弃置展示的牌,其流失X点体力,反之你摸X张牌.(X=其本回合受到对其造成伤害牌的相同牌名的牌的次数+1)',
      zhefumrfz: '蛰伏',
      zhefumrfz_info: '出牌阶段开始时,你可以将手牌中所有带有伤害类标签的牌按照任意顺序置于牌堆底或弃牌堆,你摸等量的牌.',
      yubianmrfz: '狱变',
      yubianmrfz_info: '结束阶段,你可以使用牌堆底的牌(必须合法),若你因此的使用颜色均相同,你重复这个流程.',
      yizhemrfz: '医者',
      yizhemrfz_info: '锁定技,你的【桃】不计入手牌上限;游戏开始时,你从牌堆中获得三张【桃】;你手牌中的【桃】的描述改为"①出牌阶段,对自己或在你攻击范围内的其他角色使用,目标角色回复X点体力,获得5-X点护甲(每轮开始时目标角色会失去一点因此获得的护甲).②当有角色处于濒死状态时,对该角色使用.目标角色回复X点体力,获得5-X点护甲(每轮开始时目标角色会失去一点因此获得的护甲).(X = 目标角色已损失的体力值)"',
      zhulimrfz: '铸犁',
      zhulimrfz_info: '锁定技,结束阶段,若你本回合造成过伤害,你弃置一张牌,反之,你摸两张牌且其中的♡2-9视为【桃】.',
      shuangzimrfz: '双子',
      shuangzimrfz_info: '①锁定技,你使用的牌在进入弃牌堆或造成伤害时之前视为无对应实体牌、无点数和🃏的牌;当你的手牌数少于你的体力上限时,你获得等同于你体力上限与手牌数之差的【影】;当你造成伤害后,若对应的实体牌为【影】,则令其回复等同于此次伤害数的体力,其展示所有手牌且不可响应下一张指定其为目标的【杀】.<br>②每回合限一次,你可以将一张【影】当作任意基本牌和普通锦囊牌使用,你以此法使用的【杀】不计入次数限制.',
