      jiangtumrfz_info: '锁定技,当前回合角色的手牌对你可见.',
      jieshimrfz: '揭示',
      jieshimrfz_info: '一名角色的出牌阶段开始时,你可以弃置一张牌,猜测其本阶段前三张牌分别使用的类型(对其不可见),当其本阶段使用的第一、二和三张牌结算完毕后,若你猜测正确,你摸X张牌,你可以对其造成X-1(至多为1)点伤害.(X=你此次猜对的次数)',
